using System.Net;
using System.Net.Http.Json;
using System.Text.Json;
using Microsoft.AspNetCore.Hosting;
using Microsoft.AspNetCore.Mvc.Testing;

namespace Warehouse.Tests;

[TestClass]
public class ApiTests
{
    private sealed class Factory : WebApplicationFactory<Program>
    {
        public string Db = Path.Combine(Path.GetTempPath(), $"wh-{Guid.NewGuid():N}.db");
        protected override void ConfigureWebHost(IWebHostBuilder b)
        {
            b.UseSetting("ConnectionStrings:Warehouse", $"Data Source={Db}");
        }
    }

    private static async Task<(HttpResponseMessage, JsonElement)> Send(HttpClient c, HttpMethod m, string url, object? body = null)
    {
        var r = await c.SendAsync(new HttpRequestMessage(m, url) { Content = body is null ? null : JsonContent.Create(body) });
        var text = await r.Content.ReadAsStringAsync();
        return (r, text.Length > 0 ? JsonDocument.Parse(text).RootElement.Clone() : default);
    }

    private static async Task<string> NewSupplier(HttpClient c, string name = "Acme")
    {
        var (r, j) = await Send(c, HttpMethod.Post, "/suppliers", new { name, email = "a@b.c" });
        Assert.AreEqual(HttpStatusCode.Created, r.StatusCode);
        return j.GetProperty("id").GetString()!;
    }

    private static object Prod(string sup, string sku = "S1", int stock = 5, int level = 5, int status = 0) =>
        new { sku, name = "Widget", stock, reorderLevel = level, status, supplierId = sup };

    [TestMethod]
    public async Task SupplierRoundTrip()
    {
        using var f = new Factory(); var c = f.CreateClient();
        var id = await NewSupplier(c);
        var (_, p) = await Send(c, HttpMethod.Post, "/products", Prod(id));
        var (r, j) = await Send(c, HttpMethod.Get, $"/suppliers/{id}");
        Assert.AreEqual(HttpStatusCode.OK, r.StatusCode);
        Assert.AreEqual(1, j.GetProperty("products").GetArrayLength());
        (r, j) = await Send(c, HttpMethod.Put, $"/suppliers/{id}", new { name = "New" });
        Assert.AreEqual(HttpStatusCode.OK, r.StatusCode);
        Assert.AreEqual("New", j.GetProperty("name").GetString());
        (r, j) = await Send(c, HttpMethod.Get, "/suppliers");
        Assert.AreEqual(1, j.GetArrayLength());
        (r, _) = await Send(c, HttpMethod.Delete, $"/suppliers/{id}");
        Assert.IsTrue(r.StatusCode is HttpStatusCode.NoContent or HttpStatusCode.Conflict);
    }

    [TestMethod]
    public async Task ProductRoundTripAndNeedsReorder()
    {
        using var f = new Factory(); var c = f.CreateClient();
        var sup = await NewSupplier(c);
        var (r, j) = await Send(c, HttpMethod.Post, "/products", Prod(sup, stock: 5, level: 5));
        Assert.AreEqual(HttpStatusCode.Created, r.StatusCode);
        Assert.IsTrue(j.GetProperty("needsReorder").GetBoolean());
        Assert.AreEqual(sup, j.GetProperty("supplierId").GetString());
        var id = j.GetProperty("id").GetString();

        (r, j) = await Send(c, HttpMethod.Put, $"/products/{id}", Prod(sup, stock: 6, level: 5));
        Assert.AreEqual(HttpStatusCode.OK, r.StatusCode);
        Assert.IsFalse(j.GetProperty("needsReorder").GetBoolean());

        (_, j) = await Send(c, HttpMethod.Put, $"/products/{id}", Prod(sup, stock: 1, level: 5, status: 1));
        Assert.IsFalse(j.GetProperty("needsReorder").GetBoolean());
        Assert.AreEqual(1, j.GetProperty("status").GetInt32());

        (r, j) = await Send(c, HttpMethod.Get, $"/products/{id}");
        Assert.AreEqual(HttpStatusCode.OK, r.StatusCode);
        (r, _) = await Send(c, HttpMethod.Delete, $"/products/{id}");
        Assert.AreEqual(HttpStatusCode.NoContent, r.StatusCode);
        (r, _) = await Send(c, HttpMethod.Get, $"/products/{id}");
        Assert.AreEqual(HttpStatusCode.NotFound, r.StatusCode);
    }

    [TestMethod]
    public async Task ValidationErrors()
    {
        using var f = new Factory(); var c = f.CreateClient();
        var sup = await NewSupplier(c);
        foreach (var body in new object[]
        {
            Prod(sup, stock: -1), Prod(sup, level: -1), Prod(sup, status: 7),
            Prod(Guid.NewGuid().ToString()), Prod(sup, sku: ""), Prod(sup, sku: new string('x', 21)),
        })
        {
            var (r, _) = await Send(c, HttpMethod.Post, "/products", body);
            Assert.AreEqual(HttpStatusCode.BadRequest, r.StatusCode);
        }
        var (r2, _) = await Send(c, HttpMethod.Post, "/suppliers", new { name = "" });
        Assert.AreEqual(HttpStatusCode.BadRequest, r2.StatusCode);
        (r2, _) = await Send(c, HttpMethod.Post, "/suppliers", new { name = new string('x', 101) });
        Assert.AreEqual(HttpStatusCode.BadRequest, r2.StatusCode);
    }

    [TestMethod]
    public async Task UniqueConflictsAndNotFound()
    {
        using var f = new Factory(); var c = f.CreateClient();
        var sup = await NewSupplier(c);
        var (r, _) = await Send(c, HttpMethod.Post, "/suppliers", new { name = "Acme" });
        Assert.AreEqual(HttpStatusCode.Conflict, r.StatusCode);
        await Send(c, HttpMethod.Post, "/products", Prod(sup));
        (r, _) = await Send(c, HttpMethod.Post, "/products", Prod(sup));
        Assert.AreEqual(HttpStatusCode.Conflict, r.StatusCode);
        var missing = Guid.NewGuid();
        (r, _) = await Send(c, HttpMethod.Get, $"/suppliers/{missing}");
        Assert.AreEqual(HttpStatusCode.NotFound, r.StatusCode);
        (r, _) = await Send(c, HttpMethod.Put, $"/products/{missing}", Prod(sup, "Z"));
        Assert.AreEqual(HttpStatusCode.NotFound, r.StatusCode);
        (r, _) = await Send(c, HttpMethod.Delete, $"/products/{missing}");
        Assert.AreEqual(HttpStatusCode.NotFound, r.StatusCode);
    }
}
